CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL, password_hash VARCHAR(255) NOT NULL, status ENUM('active','disabled') NOT NULL DEFAULT 'active', last_login_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, PRIMARY KEY(id), UNIQUE KEY uq_admin_email(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_roles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(100) NOT NULL,slug VARCHAR(100) NOT NULL,description VARCHAR(255) NULL,is_system TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,PRIMARY KEY(id),UNIQUE KEY uq_admin_role_slug(slug)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(100) NOT NULL,slug VARCHAR(100) NOT NULL,description VARCHAR(255) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_admin_permission_slug(slug)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),CONSTRAINT fk_admin_rp_role FOREIGN KEY(role_id) REFERENCES admin_roles(id) ON DELETE CASCADE,CONSTRAINT fk_admin_rp_permission FOREIGN KEY(permission_id) REFERENCES admin_permissions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_user_roles (admin_user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(admin_user_id,role_id),CONSTRAINT fk_admin_ur_user FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE CASCADE,CONSTRAINT fk_admin_ur_role FOREIGN KEY(role_id) REFERENCES admin_roles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,admin_user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at TIMESTAMP NOT NULL,revoked_at TIMESTAMP NULL,user_agent VARCHAR(500) NULL,ip_address VARCHAR(64) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,last_used_at TIMESTAMP NULL,PRIMARY KEY(id),UNIQUE KEY uq_admin_session_token(token_hash),CONSTRAINT fk_admin_session_user FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,admin_user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NULL,entity_id VARCHAR(100) NULL,metadata_json JSON NULL,ip_address VARCHAR(64) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_admin_audit_created(created_at),CONSTRAINT fk_admin_audit_user FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
